// D45: weapon proficiency data (generated by `npm run import:proficiency`, see docs/modules/proficiency.md).
import type { BestiaryClass, Vocation } from '../../types';

export type ProficiencyElement = 'physical' | 'fire' | 'earth' | 'energy' | 'ice' | 'holy' | 'death';
export type ProficiencySkill = 'magic' | 'shielding' | 'distance' | 'sword' | 'club' | 'axe' | 'fist' | 'fishing';
export type AugmentKind = 'baseDamage' | 'healing' | 'cooldown' | 'lifeLeech' | 'manaLeech' | 'critDamage' | 'critChance';

/**
 * Perk kinds. Percent kinds hold fractions (0.04 = 4 %); attack, defence, skills, magic levels, on-hit/on-kill,
 * range damage and range are points; an augment's cooldown is seconds (negative); homingMissile is a chance per
 * offensive spell with `levelMultiplier` × level damage.
 */
export type PerkKind =
  | 'attack' | 'defence' | 'defenceMod' | 'skill' | 'magicLevel' | 'augment' | 'bestiary' | 'boss'
  | 'critChance' | 'elementCritChance' | 'runeCritChance' | 'autoCritChance'
  | 'critDamage' | 'elementCritDamage' | 'runeCritDamage' | 'autoCritDamage'
  | 'manaLeech' | 'lifeLeech' | 'manaOnHit' | 'lifeOnHit' | 'manaOnKill' | 'lifeOnKill'
  | 'rangeDamage' | 'hitChance' | 'range' | 'autoSkillScaling' | 'spellSkillScaling' | 'healSkillScaling'
  | 'alphaStrike' | 'omegaStrike' | 'armorPenetration' | 'pierce' | 'homingMissile';

export interface Perk {
  kind: PerkKind;
  value: number;
  /** skill, autoSkillScaling, spellSkillScaling, healSkillScaling. */
  skill?: ProficiencySkill;
  /** magicLevel (also 'healing'), elementCritChance/Damage, pierce, homingMissile. */
  element?: ProficiencyElement | 'healing';
  bestiary?: BestiaryClass;
  spell?: string;
  augment?: AugmentKind;
  /** rangeDamage: distance in squares. */
  range?: number;
  levelMultiplier?: number;
}

export type WeaponType = 'axe' | 'club' | 'sword' | 'fist' | 'bow' | 'crossbow' | 'throw' | 'wand' | 'rod';

export interface WeaponSpecials {
  skills?: Partial<Record<'magic' | 'axe' | 'club' | 'sword' | 'fist' | 'distance', number>>;
  elementMagicLevel?: Partial<Record<ProficiencyElement | 'healing', number>>;
  /** Bows and crossbows: attack added to the ammunition. */
  attack?: number;
  elementAttack?: { element: ProficiencyElement; value: number };
  defenceMod?: number;
  critChance?: number;
  critDamage?: number;
  lifeLeech?: number;
  manaLeech?: number;
  hitChance?: number;
  cleave?: number;
  perfectShot?: { value: number; range: number };
}

export interface Weapon {
  id: string;
  name: string;
  type: WeaponType;
  hands: 1 | 2;
  vocations: Vocation[];
  minLevel: number;
  /** Melee and throwing weapons: physical attack (elemental part in `elementAttack`). */
  attack?: number;
  /** Wands and rods: average damage per hit, when known. */
  damage?: number;
  /** Damage element of the main attack (wands, rods, elemental weapons). */
  element?: ProficiencyElement;
  elementAttack?: { element: ProficiencyElement; value: number };
  defence?: number;
  range?: number;
  /** Item class (upgrade tier limit). */
  class?: number;
  imbuementSlots?: number;
  specials?: WeaponSpecials;
  /** Proficiency levels 1..n; each level offers one to three perks, of which one is chosen. */
  levels: Perk[][];
}

/** A dust shaping option; the value at rank r (0..10) is taken as rank0 + (rank10 − rank0) × r / 10 (estimate). */
export interface ShapingOption extends Omit<Perk, 'value'> {
  group: Vocation | 'all';
  rank0: number;
  rank10: number;
}

export interface ProficiencyFile {
  meta: { sources: string[]; weapons: number; withoutTree: string[]; issues: string[] };
  weapons: Weapon[];
  shaping: ShapingOption[];
}
